&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Based in the UK with the right to work in the UK&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Ability to travel across the UK and EMEA, with occasional travel to the US (up to 40%)&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Familiarity with MEDDICC/MEDDPICC sales methodology&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Experience working with Microsoft partners, resellers, and the Microsoft field is an advantage&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Experience selling into UK public sector, government, or regulated industries is an advantage&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Eligibility and willingness to obtain UK Security Check (SC) clearance is an advantage&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Experience with PowerShell scripting and automation workflows is an advantage&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Additional European language skills are an advantage&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-CW1&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;hr&gt;
&lt;p&gt;&lt;strong&gt;Coreview Values&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ownership Mindset&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;:&lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Take ownership. Drive outcomes.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;One Team&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;:&lt;/span&gt; &lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;One team, one goal, embracing diversity&amp;nbsp;-&amp;nbsp;to&amp;nbsp;achieve&amp;nbsp;more together.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Velocity:&lt;/span&gt;&lt;/strong&gt; &lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Decide fast. Deliver fast. Repeat.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Continuous Improvement&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;:&lt;/span&gt; &lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Curiosity drives us. We challenge the status quo.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Customer First: &lt;/span&gt;&lt;/strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Listen deeply. Solve boldly.&amp;nbsp;&lt;/span&gt;&lt;/em&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Resilience: &lt;/span&gt;&lt;/strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Steady under pressure.&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;CoreView is an organisation which values the strength that diversity brings to the workplace. As an employer, we seek to promote equal opportunity through affirmative action. All qualified applicants will therefore receive consideration for employment and will not be discriminated against based on gender/sex, race/ethnicity, disability, age or any other protected group status (such as protected veteran status) or characteristic that is protected by local legislation. &lt;/span&gt;&lt;/span&gt;&lt;/em&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&lt;strong&gt;Privacy Notice: &lt;/strong&gt;By submitting your application, you acknowledge that CoreView will process your personal data for recruitment purposes in accordance with our &lt;a href=&quot;https://www.coreview.com/data-privacy-notices-employees-candidates&quot; target=&quot;_blank&quot;&gt;Privacy Policy&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p&gt;&lt;strong&gt;Working at CreateFuture&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt;&lt;br&gt;&lt;a href=&quot;https://createfuture.com/&quot;&gt;CreateFuture&lt;/a&gt; is a Version 1 company and &lt;strong&gt;AI-native consulting partner&lt;/strong&gt; where people do work that matters and are supported to do it well. We work alongside organisations such as PayPal, adidas, NatWest, FanDuel and Money Saving Expert, building digital products and services that make a difference&amp;nbsp; while always putting people first.&lt;/p&gt;
&lt;p&gt;We’re a team of creators. We write code, shape delivery, build go-to-market strategies, develop AI solutions and create the practices that support our people. We work side by side with our clients, challenging what’s not working and helping them to build the future. Our commitment to craft, quality, and culture has helped us scale to over 600 people in just a few years.&lt;/p&gt;
&lt;p&gt;Our UK Benefits&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;35 days leave (including bank holidays).&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Private medical insurance.&lt;/li&gt;
&lt;li&gt;Enhanced parental and adoption leave.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Financial coaching + 5% pension match.&lt;/li&gt;
&lt;li&gt;40 hours of paid learning and development.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;a href=&quot;https://drive.google.com/file/d/1-uZ_KOuW1SI-xoZ0Sd0WJCisULzkYox4/view?usp=sharing&quot;&gt;&lt;em&gt;&amp;nbsp;View our full list of UK benefits.&amp;nbsp; &lt;/em&gt;&lt;br&gt;&lt;br&gt;&lt;/a&gt;CreateFuture is a&lt;a href=&quot;https://www.greatplacetowork.co.uk/certified-company/1572759&quot;&gt; Great Place to Work-Certified™ company&lt;/a&gt; and has won Best Workplaces UK multiple years in a row.&lt;/p&gt;
&lt;p&gt;Join us on our journey. Let’s create tomorrow, together, today&lt;/p&gt;
&lt;h4 data-renderer-start-pos=&quot;2571&quot;&gt;About the role and team:&lt;/h4&gt;
&lt;p&gt;You own delivery outcomes end-to-end across scope, time, budget, and quality. You bring control and transparency to the accounts and/or engagements you run, and you leverage AI to enable yourself and others to focus on the real value add work. Your consulting experience allows you to adapt quickly into different client environments and you are comfortable operating with pace and ambiguity.&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;
&lt;p&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;What you’ll be doing:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Managing overall project timelines and track progress against key milestones (across time, budget &amp;amp; quality).&lt;/li&gt;
&lt;li&gt;Managing team performance and delivery health.&lt;/li&gt;
&lt;li&gt;Identifying and managing risks, issues, and dependencies.&lt;/li&gt;
&lt;li&gt;Building relationships with internal and external stakeholders, ensuring effective and transparent communication.&lt;/li&gt;
&lt;li&gt;Providing regular progress updates and escalation of issues when necessary.&lt;/li&gt;
&lt;li&gt;Removing blockers and supporting your team in overcoming challenges.&lt;/li&gt;
&lt;li&gt;Navigating and resolving conflicts where needed.&lt;/li&gt;
&lt;li&gt;Maintaining a good level of governance i.e Keeping a clear record of decisions and progressing action items.&lt;/li&gt;
&lt;li&gt;Organising and facilitating key meetings and ceremonies.&lt;/li&gt;
&lt;li&gt;Providing constructive input and challenge to stakeholders to ensure best outcomes.&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;p-rich_text_section&quot;&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;We’d love to talk to you if you have:&lt;/strong&gt;&lt;/div&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet p-rich_text_list--nested&quot; data-stringify-type=&quot;unordered-list&quot; data-list-tree=&quot;true&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li&gt;Proven experience leading complex technical delivery within a digital transformation consultancy.&lt;/li&gt;
&lt;li&gt;Experience taking client programmes from discovery and strategy through to completion.&lt;/li&gt;
&lt;li&gt;A solid understanding of the full software development lifecycle (SDLC).&lt;/li&gt;
&lt;li&gt;Experience of End-to-end AI delivery, or hands-on use of AI in the delivery process.&lt;/li&gt;
&lt;li&gt;Experience creating and managing SOWs, including scope change and change requests.&lt;/li&gt;
&lt;li&gt;Excellent stakeholder management, building trusted relationships.&lt;/li&gt;
&lt;li&gt;Experience leading multidisciplinary teams across several workstreams.&lt;/li&gt;
&lt;li&gt;The ability to adapt Agile or hybrid delivery approaches to suit each client.&lt;/li&gt;
&lt;li&gt;A recognised delivery certification such as Scrum (PSM/CSM), SAFe, PRINCE2 or PMP would be an advantage.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3 id=&quot;What-we’ll-offer-you:&quot; data-renderer-start-pos=&quot;8044&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;What we’ll offer you:&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;We trust people to do their best work. That means flexibility over rigid rules, impact over activity, and real investment in your growth both professionally and personally. You’ll be part of a supportive, and friendly culture, surrounded by smart, curious people who care deeply about what they do.&lt;br&gt;&lt;br&gt;We offer flexible working, including hybrid and remote options. Our office hubs are located in Edinburgh, Leeds, Manchester, London and Bulgaria, with occasional travel to client sites or CreateFuture offices when needed.&lt;/p&gt;
&lt;p&gt;We trust you to manage your time balancing collaboration with client time and focused work. What matters is the impact you have, not how busy you look.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Our hiring process&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;We try to keep our hiring process clear, fair and respectful of your time. We aim to get back to everyone who applies and we will be upfront about where you are in the process.&lt;/p&gt;
&lt;p&gt;It usually looks like this:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Call with our Talent Acquisition Team&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Role specific capability interview&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Depending on the role, we might also ask you to do a short presentation, a practical or technical task or have a values focused conversation. We will explain what is involved before anything happens.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;Inclusion at CreateFuture&amp;nbsp;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;We believe diverse teams build better workplaces and better products. We want CreateFuture to be a place where people feel able to be themselves and do their best work.&lt;/p&gt;
&lt;p&gt;If you need any adjustments or support during the application process, just. We will do what we can to help.&lt;/p&gt;
&lt;p&gt;We look forward to your application!&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;Who we are:&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Burson, part of WPP, is the global communications leader built to create value for clients through reputation. With highly specialized teams, industry-leading technologies and breakthrough creative, we help brands and businesses redefine reputation as a competitive advantage so they can lead today and into the future. When you work at Burson, you are part of a global community of lifelong learners who thrive at the edge of innovation.&lt;/p&gt;
&lt;p&gt;WPP (LSE/NYSE: WPP) is the trusted growth partner for the world’s leading brands. We unite cutting-edge media intelligence and data solutions, world-class creativity, next-generation production, transformative enterprise solutions and expert strategic counsel in a single company – powered by exceptional talent and our agentic marketing platform, WPP Open, to help our clients navigate change, capture opportunity and deliver transformational growth. For more information, visit &lt;a href=&quot;WPP.com&quot;&gt;WPP.com&lt;/a&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;For more information visit&amp;nbsp;&lt;a href=&quot;https://www.bursonglobal.com/&quot;&gt;bursonglobal.com&lt;/a&gt; and follow us on &lt;a href=&quot;https://www.linkedin.com/company/burson/posts/?feedView=all&quot;&gt;LinkedIn&lt;/a&gt; and&amp;nbsp;&lt;a href=&quot;https://www.instagram.com/burson.global/?hl=en&quot;&gt;Instagram&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;More about the role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;We are looking for an experienced&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;Senior Account Director&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;with strong knowledge of the B2B technology space&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;to join our Technology practice on a&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun Highlight SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun CommentStart CommentHighlightPipeRest CommentHighlightRest SCXW91818119 BCX8&quot;&gt;12-month maternity cover contract&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun CommentHighlightPipeRest SCXW91818119 BCX8&quot;&gt;. In this role, you will take on a strategic lead and trusted consultative role across a flagship portfolio of global enterprise accounts including&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;Qualcomm, Cellnex, Wipro, Adobe, and Park Place Technologies.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW91818119 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;&amp;nbsp;You will drive high-impact B2B communication strategies, manage&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;revenue&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW91818119 BCX8&quot;&gt;&amp;nbsp;and account profitability, and lead daily team execution under the guidance of senior practice leadership.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW91818119 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This role offers the opportunity to develop under the guidance of some of the best in the industry and gain first-hand experience working on high-profile international brands.&amp;nbsp;The experience of the&amp;nbsp;team&amp;nbsp;enables us to deliver&amp;nbsp;integrated communications, from corporate, B2B and consumer communications, to digital &amp;amp; social, influencers, analyst relations, content&amp;nbsp;marketing&amp;nbsp;and public affairs. We understand technology ecosystems, consumer and business audiences, and the power of the influencer.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Having a passion for enterprise tech, telecommunications, and digital infrastructure is essential for this role as you will be leading accounts for some of the world’s most influential B2B technology leaders.&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Whether navigating telecoms infrastructure, wireless innovation, data&amp;nbsp;center&amp;nbsp;services, or global IT consulting, as we progress into a new era defined by advancements in AI, cloud, and connectivity, it’s crucial we continue to turn complex B2B technology stories into compelling, human-first narratives.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Annual salary for this role starts at £60,000.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you&#39;ll do:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;19&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Acting as a trusted senior advisor to clients, directing strategy with vision, adding value, and helping clients achieve business objectives&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
