&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deep experience in the B2B tech, telecoms, enterprise software, or digital infrastructure sectors&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;3&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong commercial skills, including budget oversight, revenue forecasting, and team resourcing&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;4&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excellent client management skills with&amp;nbsp;a track record&amp;nbsp;as a trusted advisor to senior executive stakeholders&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;5&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Leadership skills with a passion for mentoring junior staff and fostering a collaborative, inclusive team culture&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;6&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A senior storyteller and media strategist who knows how to craft compelling business narratives for business, trade, and national media&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;20&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;7&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ability to step into a high-profile account portfolio on a 12-month maternity cover and deliver immediate strategic impact&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;#LI-CY1&lt;/strong&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h3&gt;&lt;strong&gt;You belong at Burson:&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Our vision is for Burson to be the leading ‘academy company’ for creative communications professionals and emerging leaders. We provide a dynamic environment where ambitious colleagues come to elevate their skills, expand their networks, and ultimately, produce the best solutions for today’s leading brands. Our commitment to your growth is reflected in our robust benefits and people programs, which include professional development opportunities, mentorship programs with industry leaders, a vibrant and inclusive company culture fostering collaboration and innovation and packages designed to reward and retain top talent. We invest in our people because we believe their success is our success.&lt;/p&gt;
&lt;p&gt;At Burson, we’re an agency of learn-it-alls. We recognize that the things we do best, creativity and communications, require a level of nuanced understanding. That’s why it’s imperative for us to hire extraordinarily talented people of all backgrounds and identities. Without that we can’t do the essential work of inspiring bold ideas, fostering constructive dialogue, cultivating meaningful experiences, and driving innovation and creativity for our partners. Your unique point of view—your talent—is what makes you a #BursonPerson, and it’s how we deliver exceptional results for our clients, together.&lt;/p&gt;
&lt;p&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/p&gt;
&lt;p&gt;When you click the &quot;Submit Application&quot; button below, this will send any information you add below to Burson. Before you do this, we think it&#39;s a good idea to read through our &amp;nbsp;&lt;a href=&quot;https://www.bursonglobal.com/p/recruitment-privacy-notice&quot;&gt;Recruitment Privacy Policy. &lt;/a&gt;California residents should read our  &lt;a href=&quot;https://www.bursonglobal.com/p/california-recruitment-privacy-notice&quot;&gt;California Recruitment Privacy Notice. &lt;/a&gt;This explains what we do with your personal data when you apply for a role with us, and, how you can update the information you have provided us with or how to remove it.&amp;nbsp;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Introduction&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The Mechanical and Biomedical Engineering department is looking for an engineer with strong practical and analytical skills.  Working predominantly across healthcare projects, you will use your engineering skills at all stages of the development life-cycle.  You will take responsibility for design challenges and technical problems, participating in concept generation, research, design and testing.  &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Successful candidates can join us between May - October 2027. &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&lt;span class=&quot;TextRun SCXW97298115 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW97298115 BCX8&quot;&gt;There is no deadline for this role, as we recruit on a rolling basis. Once the position is filled, we will close the advert. We encourage you to apply as soon as possible.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW97298115 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW97298115 BCX8&quot;&gt; &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW97298115 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What you&#39;ll be doing &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will work within a team of highly talented, supportive and multi-disciplinary engineers on major development projects, applying your practical and analytical abilities to realise novel medical technologies for our clients around the globe. You will participate in projects covering all stages of the development life-cycle, applying novel technologies in the field of medical device development.  You will have the opportunity to create exciting cutting-edge technology in areas such as diagnostics, drug delivery, surgical and acute care, synthetic biology and digital health.  &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will be using your strong technical and interpersonal skills to make a significant contribution to development projects, from initial concepts through to final delivery. This will include: &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Concept generation &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analysis and development of engineering designs  &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Rapid Prototyping &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design and implementation of test rigs &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Design and execution of experimental test programmes &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Presenting results, both internally and to clients &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Preparing technical reports and producing high-quality documentation &lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What you can bring &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We’re looking for applicants who can demonstrate:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-start=&quot;558&quot; data-end=&quot;652&quot;&gt;An excellent academic record, studying for or having completed a relevant Engineering degree&lt;/li&gt;
&lt;li data-start=&quot;655&quot; data-end=&quot;731&quot;&gt;A solid understanding of core engineering fundamentals and physical principles&lt;/li&gt;
&lt;li data-start=&quot;734&quot; data-end=&quot;809&quot;&gt;A genuine enthusiasm for tackling real-world problems through engineering&lt;/li&gt;
&lt;li data-start=&quot;812&quot; data-end=&quot;890&quot;&gt;A creative and analytical approach to problem-solving and concept generation&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-start=&quot;892&quot; data-end=&quot;990&quot;&gt;In addition, experience in any of the following areas would be advantageous (but not essential):&lt;/p&gt;
&lt;ul&gt;
&lt;li data-start=&quot;994&quot; data-end=&quot;1118&quot;&gt;Familiarity with engineering tools such as Python/MATLAB and 3D CAD software&lt;/li&gt;
&lt;li data-start=&quot;1121&quot; data-end=&quot;1215&quot;&gt;Understanding of engineering analysis tools used in product development, such as CFD and FEA&lt;/li&gt;
