&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Strong&quot;&gt;Exploration &amp;amp; Hypothesis Development&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:40}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
