&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in selling complex systems products&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Be available to travel across France&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Be a self-starter with the ability to learn quickly&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Be comfortable working in a fast-paced environment where roles and responsibilities change quickly&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Language skills: Fluent French and English&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:279}&quot;&gt;What you´ll get:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-uuid=&quot;962d2596-0d84-4634-8122-e72620efaf3a&quot;&gt;25 paid vacation days plus RTT days, plus 4 extra global VeeaMe Days for self-care and 24 paid volunteer hours annually through Veeam Cares&lt;/li&gt;
&lt;li data-uuid=&quot;ac5169f0-07e3-489b-8abe-892be770a0b0&quot;&gt;Mandatory public health insurance with broad medical coverage&lt;/li&gt;
&lt;li data-uuid=&quot;6d7de02c-c10d-4630-8e3a-d6fc9459e7d9&quot;&gt;Employer-paid private medical, dental, optical, and wellness plan through Axa, with options for dependents&lt;/li&gt;
&lt;li data-uuid=&quot;61b12e02-8f54-4d15-96d6-bbc42318ce88&quot;&gt;Life insurance with enhanced coverage above the Social Security ceiling&lt;/li&gt;
&lt;li data-uuid=&quot;857127a3-8f58-4d62-9dd4-f69b9f89cff8&quot;&gt;State and supplementary pension contributions by Veeam&lt;/li&gt;
&lt;li data-uuid=&quot;73fa609e-fa75-463b-994c-f8b6c840141c&quot;&gt;Opportunities to learn and grow through on-demand libraries (LinkedIn Learning, O’Reilly), mentoring, workshops and learning events like our annual Global Day of Learning&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-JB1&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div data-pm-slice=&quot;1 1 [&amp;quot;ul&amp;quot;,null,&amp;quot;li&amp;quot;,{&amp;quot;style&amp;quot;:null,&amp;quot;checked&amp;quot;:null,&amp;quot;value&amp;quot;:null,&amp;quot;displayValue&amp;quot;:null,&amp;quot;backgroundColor&amp;quot;:null,&amp;quot;color&amp;quot;:null,&amp;quot;listStyleType&amp;quot;:null}]&quot; data-en-clipboard=&quot;true&quot;&gt;
&lt;p data-local-id=&quot;56095010243a&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;paragraph&quot; data-prosemirror-node-block=&quot;true&quot; data-pm-slice=&quot;1 1 []&quot;&gt;&lt;strong data-prosemirror-content-type=&quot;mark&quot; data-prosemirror-mark-name=&quot;strong&quot;&gt;Veeam Software is an equal opportunity employer&lt;/strong&gt; and does not tolerate discrimination in any form on the basis of race, color, religion, gender, age, national origin, citizenship, disability, veteran status or any other classification protected by federal, state or local law. All your information will be kept confidential.&lt;/p&gt;
&lt;p&gt;Personal data collected during the recruitment process will be processed in accordance with our &lt;a href=&quot;https://www.veeam.com/legal/recruiting-privacy-notice.html&quot;&gt;Recruiting Privacy Notice&lt;/a&gt;, which explains how your information is collected, used, and handled in connection with hiring activities. By applying for this position, you consent to this processing.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;By submitting your application, you confirm that the information provided, including any supporting documents, is complete and accurate to the best of your knowledge. Any misrepresentation, omission, or falsification may result in disqualification from consideration or, if discovered after employment begins, termination of employment.&lt;/p&gt;
&lt;/div&gt;
&lt;p&gt;&lt;a id=&quot;app&quot;&gt;&lt;/a&gt;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.fr">Jobs in France</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;&lt;strong&gt;Who we are&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;Samsara (NYSE: IOT) is the pioneer of the Connected Operations™ Cloud, which is a platform that enables organizations that depend on physical operations to harness Internet of Things (IoT) data to develop actionable insights and improve their operations. At Samsara, we are helping improve the safety, efficiency and sustainability of the physical operations that power our global economy. Representing more than 40% of global GDP, these industries are the infrastructure of our planet, including agriculture, construction, field services, transportation, and manufacturing — and we are excited to help digitally transform their operations at scale.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 300; font-family: arial, helvetica, sans-serif;&quot;&gt;Working at Samsara means you’ll help define the future of physical operations and be on a team that’s shaping an exciting array of product solutions, including Video-Based Safety, Vehicle Telematics, Apps and Driver Workflows, and Equipment Monitoring. As part of a recently public company, you’ll have the autonomy and support to make an impact as we build for the long term.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;About the role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Samsara is a fortress in a volatile market. We are a $1.9B ARR, NYSE-listed powerhouse that sells essential technology to the physical operations powering the global economy. This is a seat built for high performers and incredibly driven individuals who want to accelerate their careers — the bar for entry is high, but those who execute are well rewarded for it.&lt;/p&gt;
&lt;p&gt;While the rest of the tech scene is scaling back, our France team continued to perform above 100% last year. We are looking for territory owners who want to manage deal cycles from €&lt;strong&gt;20k to &lt;/strong&gt;&lt;strong&gt;€&lt;/strong&gt;&lt;strong&gt;200k&lt;/strong&gt;, selling a complex suite of 15+ products to 8 different personas, including MDs and Finance Directors. If you want to be pushed to your limit and rewarded with the stability of a market leader, this is the place.&lt;/p&gt;
&lt;p&gt;Whilst the role can be worked remotely anywhere in France, there is a need to visit clients in the region as required (typically fortnightly basis).&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You should apply if:&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;You want to impact the industries that run our world&lt;/strong&gt;: Your efforts will result in real-world impact—helping to keep the lights on, get food into grocery stores, and most importantly, ensure workers return home safely.&lt;/li&gt;
&lt;li&gt;Your mantra is &lt;strong&gt;#alwaysbeprospecting&lt;/strong&gt;: The world of operations is vast. Your customers are often out in the field and the best way to catch them is live on the phone. Samsara’s top reps do constant research to find companies and contacts to expand their pipeline.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You have innate curiosity in how businesses work&lt;/strong&gt;: One day you’ll meet with someone in waste management and the next you may be learning about the inner workings of a food distribution center. Our top sales team members seek to learn the ins and outs of the businesses they support in order to make a larger impact.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You are a life-long learner&lt;/strong&gt;: Samsara sales are complex. You will need to learn about businesses where you previously had little knowledge. The payoff is big but you have to be willing to put in the work.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You build genuine relationships with your customers&lt;/strong&gt;: The industries we serve have relied on pen-and-paper solutions for years and haven’t been met with the type of technology we offer. Our customers value earned trust and human relationships built over time.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;You want to be with the best:&lt;/strong&gt; Samsara’s high-performance Sales culture means you’ll be surrounded by the best and challenged to go farther than you have before.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;In this role you will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Own your destiny:&lt;/strong&gt; Operate as a pure revenue leader, responsible for &lt;strong&gt;80-90% net-new logo acquisition&lt;/strong&gt; through self-sourced pipeline.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Get In Early: &lt;/strong&gt;The France Mid-Market is a high-achieving segment in the company. The window to build something significant is open right now.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Sharpen Your Edge:&lt;/strong&gt; Access elite enablement — Command the Message and MEDDPICC coaching — built to make you a more effective closer.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Navigate Complexity:&lt;/strong&gt; Move beyond feature-pushing to sell high-level ROI and safety outcomes to sophisticated economic buyers (MDs and FDs) in the field and the boardroom.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Minimum requirements for this role:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;The Winning DNA:&lt;/strong&gt; A minimum of 18 months in a full-cycle, outbound-heavy SaaS closing role. You must have a proven history of building your own pipe from scratch.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Verified Overachievement:&lt;/strong&gt; A track record of hitting and exceeding quota in a competitive, complex environment. We’ll want to see this on your resume.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Strategic Grit:&lt;/strong&gt; Experience managing multi-stakeholder deal cycles and technical POCs. We value your ability to hunt more than the brand name on your previous CV.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Native French&lt;/strong&gt; language&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;An ideal candidate also offers:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Intellectual Curiosity:&lt;/strong&gt; You are eager to learn the inner workings of diverse industries, from waste management to food distribution, to better align our technology with their operational pain.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;A Repeatable Sales Framework:&lt;/strong&gt; You don’t rely on luck or intuition. You have a structured methodology that delivers success and you understand that consistent, high-quality inputs lead to predictable results.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;A Data-Minded Approach:&lt;/strong&gt; You are a student of your own funnel. You understand how to structure your activity—prospecting volume, discovery depth, and multi-threading—to ensure a consistent output and forecast accuracy.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Continuous Process Iteration:&lt;/strong&gt; You possess a relentless drive for self-improvement. You are someone who actively seeks feedback, iterates on their approach, and understands that evolving your tactics is the only way to stay ahead of the market.&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Total Rewards&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Samsara, we build for the people who keep the global economy moving. We want owners, not passengers, which is why &lt;a href=&quot;https://www.samsara.com/company/careers/benefits&quot;&gt;our rewards&lt;/a&gt; are designed to fuel high-impact builders. Our compensation program delivers above-market total compensation through a combination of base salary, performance-based bonus/variable pay, and equity (for eligible roles) in a high-growth public company. We meaningfully differentiate pay for our top performers, who have the opportunity to earn above-market compensation that can outpace the broader market over time.&lt;/p&gt;
&lt;p&gt;Beyond compensation, we provide the foundations that enable long-term success: a flexible, employee-led remote model, a professional development stipend, comprehensive health and parental leave plans, and more. If you’re ready to build for the long term and own the outcome, your journey starts here.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Flexible Working&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;At Samsara, we embrace a flexible working model that caters to the diverse needs of our teams. Our offices are open for those who prefer to work in-person and we also support remote work where it aligns with our operational requirements. For certain positions, being close to one of our offices or within a specific geographic area is important to facilitate collaboration, access to resources, or alignment with our service regions. In these cases, the job description will clearly indicate any working location requirements. Our goal is to ensure that all members of our team can contribute effectively, whether they are working on-site, in a hybrid model, or fully remotely. All offers of employment are contingent upon an individual’s ability to secure and maintain the legal right to work at the company and in the specified work location, if applicable.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Belonging at Samsara&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Samsara, we welcome everyone regardless of their background. All qualified applicants will receive consideration for employment without regard to race, color, religion, national origin, sex, gender, gender identity, sexual orientation, protected veteran status, disability, age, and other characteristics protected by law. We depend on the unique approaches of our team members to help us solve complex problems and want to ensure that Samsara is a place where people from all backgrounds can make an impact.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Accommodations&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Samsara is an inclusive work environment, and we are committed to ensuring equal opportunity in employment for qualified persons with disabilities. Please email &lt;a ---------- or &lt;a href=&quot;https://forms.gle/DrM6DFQUiSgfPtCVA&quot;&gt;click here&lt;/a&gt; if you require any reasonable accommodations throughout the recruiting process.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Our Commitment to Authenticity&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We use &lt;a href=&quot;https://hiretofu.com/privacyPolicy&quot;&gt;Tofu&lt;/a&gt;, a fraud detection tool, to validate the authenticity of applications and protect against identity fraud. This ensures we are connecting with real people and allows us to prioritize genuine candidates. Please see Samsara’s &lt;a href=&quot;https://www.samsara.com/legal/candidate-privacy-notice&quot;&gt;Candidate Privacy Notice&lt;/a&gt; for more information.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Fraudulent Employment Offers&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Samsara is aware of scams involving fake job interviews and offers. Please know we do not charge fees to applicants at any stage of the hiring process. Official communication about your application will only come from emails ending in ----- ----- or ----- For more information regarding fraudulent employment offers, please visit our&amp;nbsp;&lt;a href=&quot;https://samsara.com/blog/avoiding-fake-job-offers&quot;&gt;blog post here&lt;/a&gt;.&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.fr">Jobs in France</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;h4&gt;&lt;strong&gt;Join Axon and be a Force for Good.&lt;/strong&gt;&lt;/h4&gt;
&lt;p&gt;At Axon, we’re on a mission to Protect Life. We’re explorers, pursuing society’s most critical safety and justice issues with our ecosystem of devices and cloud software. Like our products, we work better together. We connect with candor and care, seeking out diverse perspectives from our customers, communities and each other.&lt;br&gt;&lt;br&gt;Life at Axon is fast-paced, challenging and meaningful. Here, you’ll take ownership and drive real change. Constantly grow as you work hard for a mission that matters at a company where you matter.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;Axon&#39;s mission is simple and bold: &lt;strong&gt;Protect Life.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We build technology that helps first responders, security teams and communities act with speed, clarity and confidence in the moments that matter most. Our Real-Time Operations (RTO) portfolio, anchored by the Fusus platform, is transforming how law enforcement, enterprise security and international agencies detect, assess and respond to threats.&lt;/p&gt;
&lt;p&gt;Fusus connects live video, alerts, sensors and location data into a unified operating picture, and the map is where that picture comes together. It shows where every officer, vehicle, camera, drone and sensor is, what state it is in, and what is happening around it. We&#39;re building a map that stays clear under pressure, so operators and responders can see what matters and act in seconds.&lt;/p&gt;
&lt;h3&gt;Your Impact&lt;/h3&gt;
&lt;p&gt;As Senior Product Manager for Maps &amp;amp; Presence, you will define and lead the roadmap for how Fusus shows the world in real time. You&#39;ll own the live map, floor plans and the presence layer: the &quot;dots on the map&quot; that tell operators who and what is where, and whether that information is fresh.&lt;/p&gt;
&lt;p&gt;You&#39;ll own the map experience operators use every shift and the map services every other team builds on. Your work will let any device, sensor or data source appear on the map in a consistent way, without bespoke work for each one. That spans body cameras, fleet vehicles, drones, CCTV, sensors and third-party devices, indoors and outdoors.&lt;/p&gt;
&lt;p&gt;You&#39;ll also lead the map in Axon&#39;s next generation of Fusus: role-based experiences built from shared components, where every role gets a map designed for its job. Your work will help responders find the nearest resource, follow an incident as it moves and reconstruct what happened afterwards, directly advancing Axon&#39;s mission to Protect Life.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Work Location: &lt;/strong&gt;This role is based out of our London office and follows a hybrid schedule. We rely on in-person collaboration and ask that team members work onsite Tuesdays through Fridays, with the flexibility to work remotely on Mondays, unless there is an approved workplace accommodation. We believe that connection fuels innovation, and our in-office culture is designed to foster meaningful teamwork, mentorship, and shared success.&lt;/p&gt;
&lt;h3&gt;What You&#39;ll Do&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Own the Maps &amp;amp; Presence product roadmap, focused on a map that is clear, consistent and fast to act from&lt;/li&gt;
&lt;li&gt;Define one behavior model for every real-time dot on the map (how each device type looks, clusters, shows state and freshness) and retire legacy formats&lt;/li&gt;
&lt;li&gt;Own the map services and contracts (layers, geo-boundaries, floor plans, the Presence API) that let other teams put new data on the map through self-service&lt;/li&gt;
&lt;li&gt;Build self-service floor plans and map layers for customer admins, so setup no longer depends on Support or Professional Services&lt;/li&gt;
&lt;li&gt;Lead the map and floor-plan components for Fusus&#39;s role-based experiences, shipping them in today&#39;s Fusus first&lt;/li&gt;
&lt;li&gt;Deliver location history (breadcrumbs) and cross-camera tracking for investigations, with Search and video teams&lt;/li&gt;
&lt;li&gt;Partner with engineering and design to ship responsive, low-latency and reliable map experiences across web and mobile&lt;/li&gt;
&lt;li&gt;Engage law enforcement and enterprise users in real-time crime centers and the field to validate needs and test improvements&lt;/li&gt;
&lt;li&gt;Use metrics and feedback to set priorities: dot freshness, map load time, presence coverage, time from alert to action&lt;/li&gt;
&lt;li&gt;Support go-to-market, training and rollout with cross-functional teams&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What Success Looks Like&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Operators trust what they see on the map: every device looks and behaves the same way, and stale data is obvious&lt;/li&gt;
&lt;li&gt;New devices and data sources appear on the map in days, without map-team engineering work&lt;/li&gt;
&lt;li&gt;Customers set up their own floor plans and layers, and filter the map to what matters to them&lt;/li&gt;
&lt;li&gt;Adoption grows across customer segments with high daily use, strong retention and positive field feedback&lt;/li&gt;
&lt;li&gt;Every second saved contributes to safer outcomes for officers, teams and the public&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What You Bring&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;6–8+ years of product management experience, including 3+ years on map-based, location or real-time products&lt;/li&gt;
&lt;li&gt;Experience building products where speed, clarity and reliability directly affect outcomes&lt;/li&gt;
&lt;li&gt;Strong grasp of geospatial and presence concepts: map rendering and clustering, layers and tiles, geofences, indoor mapping, location data quality and freshness&lt;/li&gt;
&lt;li&gt;Familiarity with live video, sensor networks, fleet or asset tracking, drones and IoT integrations&lt;/li&gt;
&lt;li&gt;Experience with platform products that other teams build on, including APIs and data contracts&lt;/li&gt;
&lt;li&gt;Track record of turning user insight into clear product direction and focused execution&lt;/li&gt;
&lt;li&gt;Proven ability to lead cross-functional teams through roadmap, design, delivery and iteration&lt;/li&gt;
&lt;li&gt;Clear communicator who drives alignment, decisions and measurable outcomes&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Why Axon&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Shape the future of how responders and security teams see and act on the world around them, creating safer outcomes for communities and organisations&lt;/li&gt;
&lt;li&gt;Join a mission-driven company with a history of innovation and impact&lt;/li&gt;
&lt;li&gt;Work alongside passionate teams building technology that protects lives&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Benefits that Benefit You&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Competitive base salary and RSUs&lt;/li&gt;
&lt;li&gt;Pension plan with matching contributions&lt;/li&gt;
&lt;li&gt;Private health insurance and cash plans&lt;/li&gt;
&lt;li&gt;30 days paid holiday plus UK public holidays&lt;/li&gt;
&lt;li&gt;Enhanced maternity and paternity leave&lt;/li&gt;
&lt;li&gt;GymPass subscription&lt;/li&gt;
&lt;li&gt;Life assurance and income protection&lt;/li&gt;
&lt;li&gt;Career growth, learning support, and wellness resources&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Don’t meet every single requirement? That&#39;s ok. At Axon, we Aim Far. We think big with a long-term view because we want to reinvent the world to be a safer, better place. We are also committed to building diverse teams that reflect the communities we serve.&lt;/p&gt;
&lt;p&gt;Studies have shown that women and people of color are less likely to apply to jobs unless they check every box in the job description. If you’re excited about this role and our mission to Protect Life but your experience doesn’t align perfectly with every qualification listed here, we encourage you to apply anyways. You may be just the right candidate for this or other roles.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Important Notes&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;The above job description is not intended as, nor should it be construed as, exhaustive of all duties, responsibilities, skills, efforts, or working conditions associated with this job. The job description may change or be supplemented at any time in accordance with business needs and conditions.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Some roles may also require legal eligibility to work in a firearms environment.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We collect personal information from applicants to evaluate candidates for employment. You may request access, deletion, or exercise other CCPA rights at&amp;nbsp;&lt;strong data-stringify-type=&quot;bold&quot;&gt;&lt;a class=&quot;c-link c-link--underline&quot; ----- target=&quot;_blank&quot; ----- ----- via our&amp;nbsp;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;https://privacyportal.onetrust.com/webform/0efc1702-9321-4119-bc9d-a06c3a1d3e4e/ca57cc26-a159-4193-9f6e-58ffe3fd2509&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://privacyportal.onetrust.com/webform/0efc1702-9321-4119-bc9d-a06c3a1d3e4e/ca57cc26-a159-4193-9f6e-58ffe3fd2509&quot; data-sk=&quot;tooltip_parent&quot;&gt;Axon Privacy Web Form&lt;/a&gt;. For more information, please see the Your California Privacy Rights section of our&amp;nbsp;&lt;a class=&quot;c-link c-link--underline&quot; href=&quot;https://www.axon.com/candidateprivacypolicy&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.axon.com/candidateprivacypolicy&quot; data-sk=&quot;tooltip_parent&quot;&gt;Applicant and Candidate Privacy Notice.&lt;/a&gt;&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;Axon’s mission is to Protect Life and is committed to the well-being and safety of its employees as well as Axon’s impact on the environment. All Axon employees must be aware of and committed to the appropriate environmental, health, and safety regulations, policies, and procedures. Axon employees are empowered to report safety concerns as they arise and activities potentially impacting the environment.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;We are an equal opportunity employer that promotes justice, advances equity, values diversity and fosters inclusion. We’re committed to hiring the best talent — regardless of race, creed, color, ancestry, religion, sex (including pregnancy), national origin, sexual orientation, age, citizenship status, marital status, disability, gender identity, genetic information, veteran status, or any other characteristic protected by applicable laws, regulations and ordinances — and empowering all of our employees so they can do their best work. If you have a disability or special need that requires assistance or accommodation during the application or the recruiting process, please email &lt;a ---------- &lt;/a&gt;&amp;nbsp;Please note that this email address is for accommodation purposes only. Axon will not respond to inquiries for other purposes.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;Phishing alert:&amp;nbsp; Axon will never ask you to pay for any part of the hiring process, including training, equipment, or background checks. We do not make job offers via text message, WhatsApp, or instant messaging platforms without a formal interview process.&amp;nbsp; All legitimate job openings are listed on our official careers page at &lt;a href=&quot;https://www.axon.com/careers&quot;&gt;https://www.axon.com/careers&lt;/a&gt;. &amp;nbsp;If you receive a suspicious offer or outreach from an email address that is not ----- or if you are asked for sensitive personal information (bank details, Social Security Number) prematurely, please ignore the message and report it to &lt;a ----------
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Cato Networks is the converged network and security cloud for the AI era.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:225,&amp;quot;335559739&amp;quot;:225,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;As AI reshapes cybersecurity, enterprises face a dual challenge: unlocking AI’s potential while defending against AI-driven attacks. Cato addresses both through a unified, cloud-native platform, providing the visibility and context to prioritize risks and stop threats in real time across users, applications, data, and AI agents.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:225,&amp;quot;335559739&amp;quot;:225,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Join us as we scale: take on ambitious technological challenges and shape the next generation of enterprise security at a company trusted by thousands of organizations worldwide.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:225,&amp;quot;335559739&amp;quot;:225,&amp;quot;335559740&amp;quot;:279}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;&lt;em&gt;THE OPPORTUNITY&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Cato Networks is building Product-Led Growth capabilities that complement its established enterprise, direct-sales, and partner-led business.&lt;/p&gt;
&lt;p&gt;We are looking for a hands-on Product Manager to own product-led customer journeys across Cato’s target markets, with a particular focus on SMB while also improving how larger enterprise customers discover, evaluate, activate, adopt, and expand Cato.&lt;/p&gt;
&lt;p&gt;For SMB customers, this may include highly self-service journeys from signup and onboarding through value realization, purchase, and expansion. For larger enterprises, PLG will complement the sales-led motion by helping customers experience value sooner, adopt more effectively, identify expansion opportunities, and create stronger product-qualified demand.&lt;/p&gt;
&lt;p&gt;This is an individual-contributor role. You will own measurable customer and business outcomes, working directly with Engineering, Design, Data, Marketing, Sales, Channel, Customer Success, and Business Operations.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What You’ll Do&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Own and improve the end-to-end PLG journey across relevant customer segments: &lt;strong&gt;discover → evaluate → activate → experience value → adopt → convert → retain → expand&lt;/strong&gt;.&lt;/li&gt;
&lt;li&gt;Define segment-specific product-led journeys for SMB and enterprise customers, balancing self-service, sales-assisted, and partner-assisted experiences.&lt;/li&gt;
&lt;li&gt;For SMB, drive simple self-service onboarding, guided configuration, sensible defaults, in-product education, packaging, upgrade paths, and purchase experiences.&lt;/li&gt;
&lt;li&gt;For enterprise customers, identify ways to accelerate evaluation, activation, time-to-value, adoption, product-qualified demand, and expansion.&lt;/li&gt;
&lt;li&gt;Define the key activation and “aha” moments for different customer segments, and improve time-to-first-value and unassisted or assisted activation.&lt;/li&gt;
&lt;li&gt;Own product requirements related to trials, free experiences where relevant, packaging, entitlements, upgrade paths, pricing UX, purchase flows, and conversion triggers.&lt;/li&gt;
&lt;li&gt;Define, instrument, and monitor PLG metrics, including activation, time-to-first-value, product adoption, conversion, product-qualified opportunities, retention, and expansion.&lt;/li&gt;
&lt;li&gt;Use product analytics, customer research, funnel analysis, and experimentation to identify friction, test hypotheses, and continuously improve outcomes.&lt;/li&gt;
&lt;li&gt;Partner with Sales, Marketing, Channel, Customer Success, Finance, and Business Operations to create seamless product-led, sales-assisted, and partner-assisted journeys.&lt;/li&gt;
&lt;li&gt;Identify product-usage and behavioral signals that can trigger contextual recommendations, expansion opportunities, partner engagement, or sales outreach.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What You Bring&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;5+ years of Product Management experience&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;in B2B SaaS.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;2&quot; data-aria-level=&quot;1&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deep understanding of Product-Led Growth&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;, including SaaS metrics, freemium and trial models, and PLG-driven customer journeys.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
